package com.solarmind.controller; import com.solarmind.dto.request.AuthRequests.*; import com.solarmind.dto.response.AuthResponse; import com.solarmind.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController { private final AuthService s; public AuthController(AuthService s){this.s=s;} @PostMapping("/register") ResponseEntity<AuthResponse> register(@Valid @RequestBody RegisterRequest r){return ResponseEntity.status(201).body(s.register(r));} @PostMapping("/login") AuthResponse login(@Valid @RequestBody LoginRequest r){return s.login(r);} }
